-- Difficulté des donjons : réglages de chaque niveau (l'IV par défaut des adversaires devient
-- celui du niveau facile) et difficulté de chaque donjon livré, sans toucher au reste.
UPDATE "balance_settings" SET "data" = jsonb_set("data" #- '{dungeons,defaultOpponentIv}', '{dungeons,difficulties}', jsonb_build_object('easy', '{"name":"Facile","levelBonus":0,"bossHpMultiplier":1,"timeMultiplier":1,"moneyMultiplier":1}'::jsonb || jsonb_build_object('opponentIv', COALESCE(("data" #>> '{dungeons,defaultOpponentIv}')::int, 15))) || '{"hard":{"name":"Difficile","levelBonus":10,"opponentIv":20,"bossHpMultiplier":1.25,"timeMultiplier":1.25,"moneyMultiplier":1.5},"veryHard":{"name":"Très difficile","levelBonus":15,"opponentIv":25,"bossHpMultiplier":1.5,"timeMultiplier":1.5,"moneyMultiplier":2},"extreme":{"name":"Extrême","levelBonus":20,"opponentIv":31,"bossHpMultiplier":1.5,"timeMultiplier":2,"moneyMultiplier":3}}'::jsonb) WHERE "data" ? 'dungeons' AND NOT ("data" -> 'dungeons' ? 'difficulties');
--> statement-breakpoint
UPDATE "dungeons" SET "difficulty" = 'veryHard' WHERE "difficulty" = 'easy' AND "id" IN ('mega-florizarre', 'mega-dracaufeu-x', 'mega-dracaufeu-y', 'mega-tortank', 'mega-meganium', 'mega-aligatueur', 'mega-jungko', 'mega-brasegali', 'mega-laggron');
--> statement-breakpoint
UPDATE "dungeons" SET "difficulty" = 'hard' WHERE "difficulty" = 'easy' AND "id" IN ('mega-dardargnan', 'mega-roucarnage', 'mega-raichu-x', 'mega-raichu-y', 'mega-melodelfe', 'mega-alakazam', 'mega-empiflor', 'mega-flagadoss', 'mega-ectoplasma', 'mega-staross', 'mega-leviator', 'mega-dracolosse', 'mega-pharamp', 'mega-steelix', 'mega-cizayox', 'mega-demolosse', 'mega-tyranocif', 'mega-gardevoir', 'mega-galeking', 'mega-charmina', 'mega-elecsprint', 'mega-sharpedo', 'mega-camerupt', 'mega-altaria', 'mega-branette', 'mega-eoko', 'mega-oniglali', 'mega-drattak', 'mega-metalosse', 'mega-etouraptor', 'mega-lockpin', 'mega-carchacrok', 'mega-carchacrok-z', 'mega-lucario', 'mega-lucario-z', 'mega-blizzaroi', 'mega-gallame', 'mega-momartik');
--> statement-breakpoint
UPDATE "dungeons" SET "difficulty" = 'extreme' WHERE "difficulty" = 'easy' AND "id" IN ('mega-mewtwo-x', 'mega-mewtwo-y');
